content.content:
1	// JusPrin's Preferences window (canvas "JusPrin v2", Preferences, decided
2	// 2026-10-21): a list of sections on the left and the chosen one beside it.
3	// The app reads and writes every setting, under the keys OrcaSlicer's own
4	// dialog uses, and sends what is stored after each change; the page only
5	// says what to change. The Agent section is where the agent is set up, the
6	// first time too: every surface that finds no agent opens it there
7	// (decided 2026-10-23). Agent and Account draw the connection rows of
8	// AgentConnection.tsx.
9	
10	import { useEffect, useState } from 'react';
11	import {
12	  AccountStatusPayload,
13	  CreditAccount,
14	  DragAction,
15	  McpCatalogPayload,
16	  McpPreviewPayload,
17	  McpStatusPayload,
18	  McpToolInfo,
19	  PreferencesPayload,
20	  PreferencesSection,
21	  SavedKeyInfo,
22	  SetupStatusPayload,
23	} from '../bridge/protocol';
24	import { AccountBox } from './AccountBox';
25	import { AccountRow, ProviderKeys, ToolGroup } from './AgentConnection';
26	import { balanceRows } from './BalancePanel';
27	import { creditCount, creditNumber, TIER_NAMES } from '../credits';
28	import { MarkdownMessage } from './MarkdownMessage';
29	import { Progress } from './Progress';
30	import { ActionMenu } from './ChatNavigation';
31	import { SetupLocalTool } from './SetupLocalTool';
32	
33	const SECTIONS: { id: PreferencesSection; label: string; icon: string }[] = [
34	  { id: 'account', label: 'Account', icon: 'user' },
35	  { id: 'agent', label: 'AI', icon: 'bot' },
36	  { id: 'appearance', label: 'Appearance', icon: 'palette' },
37	  { id: 'view3d', label: '3D view', icon: 'box' },
38	  { id: 'projects', label: 'Projects & files', icon: 'folder' },
39	  { id: 'updates', label: 'Updates', icon: 'refresh-cw' },
40	];
41	
42	// What each mouse button's drag can do, in OrcaSlicer's order.
43	const DRAG_ACTIONS: { value: DragAction; label: string }[] = [
44	  { value: 'rotate', label: 'Turn the view' },
45	  { value: 'pan', label: 'Pan' },
46	  { value: 'none', label: 'Nothing' },
47	];
48	
49	export interface PreferencesActions {
50	  // One setting, by the name the app's settings use.
51	  set: (name: string, value: string | boolean) => void;
52	  // A command: choose_downloads, show_versions, open_update, check_updates,
53	  // skip_update (with the version), restart, orca_preferences.
54	  run: (action: string, details?: Record<string, string>) => void;
55	  checkKey: (provider: string, apiKey: string) => void;
56	  cancelCheck: () => void;
57	  removeKey: (provider: string) => void;
58	  refreshTools: () => void;
59	  previewTool: (toolId: string) => void;
60	  connectTool: (toolId: string) => void;
61	  revealTool: (toolId: string) => void;
62	  signIn: () => void;
63	  cancelSignIn: () => void;
64	  getMoreCredits: () => void;
65	  refreshAccountBox: () => void;
66	}
67	
68	export interface PreferencesProps {
69	  preferences: PreferencesPayload;
70	  setup: SetupStatusPayload;
71	  savedKeys: SavedKeyInfo[];
72	  account: AccountStatusPayload;
73	  // The signed-in account's credits and usage; null with no account or
74	  // before it answers.
75	  creditAccount: CreditAccount | null;
76	  chatTitles: Record<string, string>;
77	  // The box the server fills near the top of Account; null for none.
78	  accountBox: string | null;
79	  mcpCatalog: McpCatalogPayload | null;
80	  mcpPreview: McpPreviewPayload | null;
81	  mcpStatus: McpStatusPayload;
82	  actions: PreferencesActions;
83	  // Done on an AI tool, for a window opened to close once one is connected.
84	  onToolDone?: () => void;
85	}
86	
87	// The JusPrin account row, as Account and Agent both draw it.
88	function JusPrinAccount({ savedKeys, account, actions }: {
89	  savedKeys: SavedKeyInfo[]; account: AccountStatusPayload; actions: PreferencesActions;
90	}) {
91	  return (
92	    <AccountRow account={savedKeys.find((key) => key.provider === 'jusprin')} status={account} onSignIn={actions.signIn}
93	      onCancel={actions.cancelSignIn} onSignOut={() => actions.removeKey('jusprin')} />
94	  );
95	}
96	
97	function Row({ title, detail, children }: { title: string; detail?: React.ReactNode; children?: React.ReactNode }) {
98	  return (
99	    <div className="prefs-row">
100	      <div className="prefs-row-copy">
101	        <span className="prefs-row-title">{title}</span>
102	        {detail && <span className="prefs-row-detail">{detail}</span>}
103	      </div>
104	      {children}
105	    </div>
106	  );
107	}
108	
109	function Check({ title, detail, checked, onChange }: {
110	  title: string; detail: string; checked: boolean; onChange: (checked: boolean) => void;
111	}) {
112	  return (
113	    <div className="prefs-row">
114	      <button type="button" role="checkbox" aria-checked={checked} className="printer-form-check prefs-check"
115	        onClick={() => onChange(!checked)}>
116	        <span className="printer-form-check-box">{checked && <span className="jp-icon jp-icon-check" aria-hidden="true" />}</span>
117	        <span className="printer-form-check-copy">
118	          <span>{title}</span>
119	          <span className="printer-form-check-detail">{detail}</span>
120	        </span>
121	      </button>
122	    </div>
123	  );
124	}
125	
126	function Segmented<T extends string>({ label, options, value, onChange }: {
127	  label: string; options: { value: T; label: string }[]; value: T; onChange: (value: T) => void;
128	}) {
129	  return (
130	    <div className="jp-segmented prefs-segmented" role="radiogroup" aria-label={label}>
131	      {options.map((option) => (
132	        <button key={option.value} type="button" role="radio" aria-checked={option.value === value}
133	          className={option.value === value ? 'jp-segment selected' : 'jp-segment'} onClick={() => onChange(option.value)}>
134	          {option.label}
135	        </button>
136	      ))}
137	    </div>
138	  );
139	}
140	
141	function Select<T extends string>({ label, options, value, onChange, searchable = false }: {
142	  label: string; options: { value: T; label: string }[]; value: T; onChange: (value: T) => void; searchable?: boolean;
143	}) {
144	  return (
145	    <div className="prefs-select">
146	      <ActionMenu
147	        appearance="select"
148	        label={label}
149	        text={options.find((option) => option.value === value)?.label ?? value}
150	        items={options.map((option) => ({
151	          key: option.value,
152	          label: option.label,
153	          current: option.value === value,
154	          onSelect: () => { if (option.value !== value) onChange(option.value); },
155	        }))}
156	        search={searchable ? { label: `Find a ${label.toLowerCase()}`, noMatch: (query) => `No ${label.toLowerCase()} matches “${query}”` } : undefined}
157	      />
158	    </div>
159	  );
160	}
161	
162	function Group({ title, tag, children }: { title: string; tag?: string; children: React.ReactNode }) {
163	  return (
164	    <div className="prefs-group">
165	      <div className="prefs-group-head">
166	        <h3 className="prefs-group-title">{title}</h3>
167	        {tag && <span className="prefs-group-tag">{tag}</span>}
168	      </div>
169	      {children}
170	    </div>
171	  );
172	}
173	
174	// A gateway day, YYYY-MM-DD, as "5 Nov". The day is the gateway's, so it is
175	// read as UTC: a local reading would move it a day west of Greenwich.
176	function dayLabel(date: string): string {
177	  return new Date(`${date}T00:00:00Z`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
178	}
179	
180	const USAGE_DAYS = 30;
181	// Rows shown before "See all activity".
182	const ACTIVITY_ROWS = 5;
183	
184	// The 30 days the usage covers, oldest first, today last.
185	function usageDays(now: Date): string[] {
186	  return Array.from({ length: USAGE_DAYS }, (_, index) =>
187	    new Date(now.getTime() - (USAGE_DAYS - 1 - index) * 86_400_000).toISOString().slice(0, 10));
188	}
189	
190	// The account's plan, credits and usage (boards 4a to 4c on the canvas's
191	// "Agent setup & Preferences" page): a bar for each kind of credit as the
192	// composer's panel draws them, then usage per day with totals per chat.
193	function AccountCredits({ account, chatTitles, onGetMore }: {
194	  account: CreditAccount; chatTitles: Record<string, string>; onGetMore: () => void;
195	}) {
196	  const [allActivity, setAllActivity] = useState(false);
197	  const usage = account.usage_30d;
198	  const byDay = new Map(usage.days.map((day) => [day.date, day.credits]));
199	  const days = usageDays(new Date());
200	  const most = Math.max(0, ...days.map((day) => byDay.get(day) ?? 0));
201	  const activity = allActivity ? usage.activity : usage.activity.slice(0, ACTIVITY_ROWS);
202	  return (
203	    <>
204	      <div className="prefs-credits-plan">
205	        <div className="prefs-row-copy">
206	          <span className="prefs-credits-plan-name">{account.plan?.name ?? 'Pay as you go'}</span>
207	          <span className="prefs-intro">
208	            {account.plan
209	              ? (account.plan.renews_at ? `Renews ${dayLabel(account.plan.renews_at.slice(0, 10))}.` : '')
210	              : 'Only messages you send cost credits.'}
211	          </span>
212	        </div>
213	        <button type="button" className="primary" onClick={onGetMore}>Get more credits</button>
214	      </div>
215	      <div className="prefs-credits">
216	        <div className="prefs-credits-card">
217	          <strong className="prefs-credits-total">{creditCount(account.credits.total)} left</strong>
218	          {balanceRows(account).map((row) => (
219	            <div key={row.key} className="credit-lot prefs-credits-lot">
220	              <div className="credit-lot-line">
221	                <strong>{row.name}</strong>
222	                <span>{creditNumber(row.left)} of {creditNumber(row.of)} left</span>
223	              </div>
224	              <div className="credit-lot-bar">
225	                <div className="credit-lot-fill" style={{ width: `${row.of > 0 ? Math.min(row.left / row.of, 1) * 100 : 0}%` }} />
226	              </div>
227	              <span className="credit-lot-date">{row.date}</span>
228	            </div>
229	          ))}
230	        </div>
231	        <p className="prefs-note">Expiring credits are used first.</p>
232	      </div>
233	      <div className="prefs-usage" aria-label="Usage" role="group">
234	        <h3 className="prefs-group-title">Usage</h3>
235	        <div className="prefs-row-copy">
236	          <span className="prefs-credits-plan-name">{creditCount(usage.credits)}</span>
237	          <span className="prefs-note">in the last 30 days</span>
238	        </div>
239	        <div className="prefs-usage-chart">
240	          <div className="prefs-usage-bars">
241	            {days.map((day) => {
242	              const credits = byDay.get(day) ?? 0;
243	              return <div key={day} className="prefs-usage-bar" title={`${dayLabel(day)}: ${creditCount(credits)}`}
244	                style={{ height: `${most > 0 ? (credits / most) * 100 : 0}%` }} />;
245	            })}
246	            {most > 0 && <span className="prefs-usage-most">{creditNumber(most)}</span>}
247	          </div>
248	          <div className="prefs-usage-axis">
249	            <span>{dayLabel(days[0])}</span>
250	            <span>{dayLabel(days[Math.floor(USAGE_DAYS / 2)])}</span>
251	            <span>{dayLabel(days[USAGE_DAYS - 1])}</span>
252	          </div>
253	        </div>
254	        {usage.activity.length > 0 ? (
255	          <table className="prefs-usage-table">
256	            <thead>
257	              <tr><th>Date</th><th>Chat</th><th>Tier</th><th>Messages</th><th>Credits</th></tr>
258	            </thead>
259	            <tbody>
260	              {activity.map((row, index) => 'kind' in row ? (
261	                <tr key={index}>
262	                  <td>{dayLabel(row.date)}</td><td>{row.title}</td><td /><td /><td>+{creditNumber(row.credits)}</td>
263	                </tr>
264	              ) : (
265	                <tr key={index}>
266	                  <td>{dayLabel(row.date)}</td>
267	                  <td>{(row.chat_id !== null && chatTitles[row.chat_id]) || 'A chat not on this computer'}</td>
268	                  <td>{TIER_NAMES[row.tier]}</td>
269	                  <td>{creditNumber(row.messages)}</td>
270	                  <td>{creditNumber(row.credits)}</td>
271	                </tr>
272	              ))}
273	            </tbody>
274	          </table>
275	        ) : (
276	          <p className="prefs-note">No messages in the last 30 days.</p>
277	        )}
278	        {!allActivity && usage.activity.length > ACTIVITY_ROWS && (
279	          <button type="button" className="link prefs-inline-link" onClick={() => setAllActivity(true)}>See all activity</button>
280	        )}
281	      </div>
282	    </>
283	  );
284	}
285	
286	function AccountSection({ savedKeys, account, creditAccount, chatTitles, accountBox, actions, onAgent }: {
287	  savedKeys: SavedKeyInfo[]; account: AccountStatusPayload; creditAccount: CreditAccount | null;
288	  chatTitles: Record<string, string>; accountBox: string | null; actions: PreferencesActions; onAgent: () => void;
289	}) {
290	  const signedIn = savedKeys.some((key) => key.provider === 'jusprin');
291	  // On the person's own API key there is no account to offer anything for.
292	  const ownKey = !signedIn && savedKeys.length > 0;
293	  // The server's box is asked for when Account opens, after a sign-in or
294	  // out, and on coming back from the browser, where a pack may have been
295	  // bought.
296	  useEffect(() => {
297	    if (ownKey)
298	      return;
299	    actions.refreshAccountBox();
300	    const refresh = () => actions.refreshAccountBox();
301	    window.addEventListener('focus', refresh);
302	    return () => window.removeEventListener('focus', refresh);
303	    // eslint-disable-next-line react-hooks/exhaustive-deps
304	  }, [signedIn, ownKey]);
305	  return (
306	    <section className="prefs-section prefs-account" aria-label="Account">
307	      <h2 className="prefs-title">Account</h2>
308	      {!ownKey && accountBox && <AccountBox key={accountBox} html={accountBox} />}
309	      <JusPrinAccount savedKeys={savedKeys} account={account} actions={actions} />
310	      {signedIn && creditAccount && (
311	        <AccountCredits account={creditAccount} chatTitles={chatTitles} onGetMore={actions.getMoreCredits} />
312	      )}
313	      {signedIn ? (
314	        <p className="prefs-note">Signing out keeps your projects, printers and API keys on this computer.</p>
315	      ) : (
316	        <p className="prefs-note">
317	          Local work never needs an account. Your own API key or AI tool works without one; set those up in the{' '}
318	          <button type="button" className="link prefs-inline-link" onClick={onAgent}>AI</button> section.
319	        </p>
320	      )}
321	    </section>
322	  );
323	}
324	
325	function AgentSection({ agent, setup, savedKeys, account, mcpCatalog, actions, onConnectTool }: {
326	  agent: PreferencesPayload['agent']; setup: SetupStatusPayload; savedKeys: SavedKeyInfo[]; account: AccountStatusPayload;
327	  mcpCatalog: McpCatalogPayload | null; actions: PreferencesActions; onConnectTool: (tool: McpToolInfo) => void;
328	}) {
329	  // The tools are looked for once each time the section opens.
330	  useEffect(() => {
331	    actions.refreshTools();
332	    // eslint-disable-next-line react-hooks/exhaustive-deps
333	  }, []);
334	  return (
335	    <section className="prefs-section" aria-label="AI">
336	      <div className="prefs-head">
337	        <h2 className="prefs-title">AI</h2>
338	        <p className="prefs-intro">The ways AI can think. Set up as many as you like; each chat picks a model from them.</p>
339	      </div>
340	      <JusPrinAccount savedKeys={savedKeys} account={account} actions={actions} />
341	      <ProviderKeys heading setup={setup} savedKeys={savedKeys} onCheck={actions.checkKey} onCancel={actions.cancelCheck}
342	        onRemove={actions.removeKey} />
343	      <ToolGroup heading tools={mcpCatalog?.tools ?? []} onConnect={onConnectTool} onLookAgain={actions.refreshTools} />
344	      <Group title="New chats start with">
345	        {agent.newChatChoices.length > 0 ? (
346	          <Row title="Model" detail="A chat keeps the model it started with.">
347	            <Select label="Model" value={agent.newChatProvider} onChange={(provider) => actions.set('newChatProvider', provider)}
348	              options={agent.newChatChoices.map((choice) => ({ value: choice.provider, label: `${choice.model} · ${choice.label}` }))} />
349	          </Row>
350	        ) : (
351	          <Row title="Model" detail="Add a key above, and new chats start with that provider’s model." />
352	        )}
353	      </Group>
354	      <div className="prefs-callout">
355	        <span className="jp-icon jp-icon-lock" aria-hidden="true" />
356	        <p>
357	          The provider a chat uses receives your messages, the open project’s settings and anything you attach. With a
358	          JusPrin account, JusPrin receives them and passes them on to the model provider it uses. JusPrin doesn’t send
359	          your keys anywhere else.
360	        </p>
361	      </div>
362	    </section>
363	  );
364	}
365	
366	function AppearanceSection({ appearance, set, run }: {
367	  appearance: PreferencesPayload['appearance']; set: PreferencesActions['set']; run: PreferencesActions['run'];
368	}) {
369	  // "Later" puts the offer away for as long as the same language waits.
370	  const [later, setLater] = useState<string | null>(null);
371	  return (
372	    <section className="prefs-section" aria-label="Appearance">
373	      <h2 className="prefs-title">Appearance</h2>
374	      <div>
375	        <Row title="Language" detail="Takes effect when JusPrin restarts. Your project is saved first.">
376	          <Select label="Language" value={appearance.language} searchable
377	            options={appearance.languages.map((language) => ({ value: language.code, label: language.name }))}
378	            onChange={(code) => set('language', code)} />
379	        </Row>
380	        {appearance.restartFor && later !== appearance.restartFor && (
381	          <div className="prefs-callout prefs-restart" role="status">
382	            <span className="jp-icon jp-icon-refresh-cw" aria-hidden="true" />
383	            <p>JusPrin will use {appearance.restartFor} after it restarts.</p>
384	            <button type="button" className="primary" onClick={() => run('restart')}>Restart now</button>
385	            <button type="button" className="link" onClick={() => setLater(appearance.restartFor)}>Later</button>
386	          </div>
387	        )}
388	        <Row title="Theme" detail="Changes every window, including the 3D view.">
389	          <Segmented label="Theme" value={appearance.theme} onChange={(theme) => set('theme', theme)}
390	            options={[{ value: 'light', label: 'Light' }, { value: 'dark', label: 'Dark' }]} />
391	        </Row>
392	        <Row title="Units" detail="For sizes, positions and distances.">
393	          <Segmented label="Units" value={appearance.units} onChange={(units) => set('units', units)}
394	            options={[{ value: 'mm', label: 'Millimetres' }, { value: 'in', label: 'Inches' }]} />
395	        </Row>
396	      </div>
397	    </section>
398	  );
399	}
400	
401	function View3dSection({ view, set }: { view: PreferencesPayload['view3d']; set: PreferencesActions['set'] }) {
402	  return (
403	    <section className="prefs-section" aria-label="3D view">
404	      <h2 className="prefs-title">3D view</h2>
405	      <Group title="Moving the view">
406	        <Row title="Controls" detail="Mouse: drag to turn, right-drag to pan. Touchpad: Alt-drag to turn, Shift-drag to pan.">
407	          <Select label="Controls" value={view.navigation} onChange={(style) => set('navigation', style)}
408	            options={[{ value: 'mouse', label: 'Mouse' }, { value: 'touchpad', label: 'Touchpad' }]} />
409	        </Row>
410	        <Check title="Zoom toward the pointer" detail="Instead of toward the middle of the view." checked={view.zoomToPointer}
411	          onChange={(on) => set('zoomToPointer', on)} />
