  box-shadow: inset -1px 0 0 0 var(--border-subtle);
}

.prefs-nav-item {
  justify-content: flex-start;
  width: 100%;
  height: var(--preferences-nav-row-height);
  padding: 0 8px;
  border: 0;
  border-radius: var(--radius-small);
  font: var(--font-body);
  color: var(--text-primary);
  text-align: left;
}

.prefs-nav-item:hover:enabled {
  border: 0;
  background: var(--surface-raised-hover);
}

.prefs-nav-item[aria-current='page'] {
  background: var(--surface-selected);
  font: var(--font-body-bold);
}

.prefs-nav-dot {
  margin-left: auto;
}

.prefs-dot {
  flex: 0 0 auto;
  width: var(--status-dot-size);
  height: var(--status-dot-size);
  border-radius: var(--radius-full);
  background: var(--action-primary);
}

.prefs-orca {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: auto;
  padding: 12px 8px 0;
  box-shadow: inset 0 1px 0 0 var(--border-subtle);
}

button.link.prefs-orca-link {
  align-self: flex-start;
  gap: 4px;
  padding: 0;
}

.prefs-orca-note {
  margin: 0;
  font: var(--font-label);
  color: var(--text-tertiary);
}

.prefs-content {
  flex: 1 1 auto;
  min-width: 0;
  overflow: auto;
  padding: 24px 32px 32px;
