cd ~/Projects/JusPrin/src/slic3r/GUI/JusPrin/AgentUI && python3 - <<'EOF'
p='src/components/Preferences.tsx'
s=open(p).read()
rep=[
("const SECTIONS: { id: PreferencesSection; label: string; icon: string }[] = [\n  { id: 'account', label: 'Account', icon: 'user' },\n  { id: 'agent', label: 'AI', icon: 'bot' },",
 "// A hint is a second, smaller line under the label, for a label that needs it.\nconst SECTIONS: { id: PreferencesSection; label: string; hint?: string; icon: string }[] = [\n  { id: 'account', label: 'Account', icon: 'user' },\n  { id: 'agent', label: 'BYOAI', hint: 'Bring Your Own AI', icon: 'bot' },"),
("""            <span className={`jp-icon jp-icon-${entry.icon}`} aria-hidden="true" />
            <span>{entry.label}</span>""",
"""            <span className={`jp-icon jp-icon-${entry.icon}`} aria-hidden="true" />
            {entry.hint ? (
              <span className="prefs-nav-copy" aria-label={`${entry.label}, ${entry.hint}`}>
                <span>{entry.label}</span>
                <span className="prefs-nav-hint">{entry.hint}</span>
              </span>
            ) : (
              <span>{entry.label}</span>
            )}"""),
("onClick={onAgent}>AI</button> section.", "onClick={onAgent}>BYOAI</button> section."),
("""    <section className="prefs-section" aria-label="AI">
      <div className="prefs-head">
        <h2 className="prefs-title">AI</h2>
        <p className="prefs-intro">The ways AI can think. Set up as many as you like; each chat picks a model from them.</p>""",
"""    <section className="prefs-section" aria-label="BYOAI">
      <div className="prefs-head">
        <h2 className="prefs-title">BYOAI</h2>
        <p className="prefs-intro">Bring Your Own AI. Set up as many as you like; each chat picks a model from them.</p>"""),
]
for a,b in rep:
    assert s.count(a)==1,a[:60]
    s=s.replace(a,b)
open(p,'w').write(s)

p='src/styles.css'
s=open(p).read()
a=""".prefs-nav-dot {
  margin-left: auto;
}
"""
b=""".prefs-nav-dot {
  margin-left: auto;
}

/* A label with a hint under it: the row grows to fit both lines. */
.prefs-nav-item:has(.prefs-nav-copy) {
  height: auto;
  min-height: var(--preferences-nav-row-height);
  padding-top: 6px;
  padding-bottom: 6px;
}

