// The Agent page in its welcome-back mode (?panel=welcome): the window shown
// once after JusPrin v1's setup was imported. It speaks the same bridge as
// Preferences, so the account v1 was signed in to is checked and signed in to
// again by the same host code.

import { useEffect, useMemo, useReducer } from 'react';
import { BridgeClient, Transport } from './bridge/client';
import { initialState, reducer } from './state/store';
import { applyAppearance } from './tokens';
import { BridgeErrorPane, ConnectingPane } from './components/Panels';
import { WelcomeBack, WelcomeBackActions } from './components/WelcomeBack';

export function WelcomeApp({ getTransport }: { getTransport: () => Transport | null }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  const client = useMemo(
    () =>
      new BridgeClient({
        getTransport,
        onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
        onEnvelope: (envelope) => dispatch({ kind: 'host', envelope }),
      }),
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  const actions = useMemo<WelcomeBackActions>(
    () => ({
      checkAccount: () => client.send('account_check', {}),
      signIn: () => client.send('account_sign_in', {}),
      cancelSignIn: () => client.send('account_cancel', {}),
      close: () => client.send('shell_action', { action: 'close' }),
    }),
    [client],
  );

  if (state.connection !== 'connected' && state.connection !== 'connecting') {
    return (
      <div className="app">
        <BridgeErrorPane title="This window could not reach JusPrin" detail={state.connectionDetail}
          diagnostics={state.diagnostics} onRetry={() => client.retry()} />
      </div>
    );
  }
  if (!state.welcomeBack) return <div className="app"><ConnectingPane /></div>;

  return (
    <div className="app app--welcome">
      <WelcomeBack report={state.welcomeBack} account={state.savedKeys.find((key) => key.provider === 'jusprin')}
        status={state.account} actions={actions} subscription={state.creditAccount?.v1_subscription} />
    </div>
  );
}
// app reads the account either one brought.
export type SignInPhase = 'idle' | 'browser' | 'email' | 'checking';

// The server's refusal of the last code, password or request for a code.
export type EmailRefusal = '' | 'wrong_code' | 'expired_code' | 'too_many_tries' | 'too_many_codes' | 'wrong_password';

// The email door while signIn is 'email': the person picks an emailed code
// or the password ('choose'), or the app waits for the code ('code').
// 'expired_code' is a code that no longer works: it expired or was tried too
// often.
export interface EmailSignIn {
  step: 'choose' | 'code';
  email: string;
  // A code, a password or a request for a code is with the server.
  busy: boolean;
  refusal: EmailRefusal;
  // A new code went out because the person asked for one.
  codeResent: boolean;
}

// One file an OrcaSlicer import brought, or could not. renamedTo is set for
// a copy imported under a new name because JusPrin had the name; reason,
// already worded, for one not imported.
export interface ImportResultItem {
  kind: 'printer' | 'filament' | 'process';
  name: string;
  renamedTo: string;
  imported: boolean;
  reason: string;
}

export interface OnboardingState {
  visible: boolean;
  step: OnboardingStep;
  // Bring OrcaSlicer's printers, what that import brought, or the
  // add-printer form.
  printersScreen: 'orca_import' | 'import_result' | 'add_printer';
  signIn: SignInPhase;
  email: EmailSignIn | null;
  // A JusPrin v1 import ran: the offer says v1 subscribers keep their price.
  v1Imported: boolean;
  // Why the last sign-in did not finish, already worded.
  signInError: string;
  // Set once the sign-in is saved: the welcome's card says who signed in.
  accountEmail: string;
  agentConfigured: boolean;
// The Agent group at the top of Home's right column (boards first-run-09 and
// 10). While no agent is set up it holds the welcome's three doors under "Set
// up the agent"; right after signing in it shows the account and its
// credits, once, until the person dismisses it. The host says which.

import type { OnboardingState } from '../bridge/protocol';
import { balanceRows } from '../../../AgentUI/src/components/BalancePanel';
import { SIGNUP_CREDITS, creditCount, creditNumber } from '../../../AgentUI/src/credits';
import { ConnectedGlyph } from './Glyphs';
import { OwnAccountDoor, SignInDoor } from './Onboarding';

type Action = (type: string, payload?: object) => void;

function Account({ onboarding, onAction }: { onboarding: OnboardingState; onAction: Action }) {
  const account = onboarding.account;
  return (
    <div className="agent-card">
      <div className="agent-card-head">
        <ConnectedGlyph />
        <span className="agent-card-title">
          <strong>Signed in as {onboarding.accountEmail}</strong>
        </span>
        <button type="button" className="onboarding-link agent-card-hide" onClick={() => onAction('agent_card_dismiss')}>
          Hide
        </button>
      </div>
      {account && (
        <>
          <strong>{creditCount(account.credits.total)} left</strong>
          {balanceRows(account).map((row) => (
            <div key={row.key} className="agent-card-lot">
              <div className="agent-card-lot-line">
                <strong>{row.name}</strong>
                <span>{creditNumber(row.left)} of {creditNumber(row.of)} left</span>
              </div>
              <div className="agent-card-bar">
                <span style={{ width: `${row.of > 0 ? Math.min(row.left / row.of, 1) * 100 : 0}%` }} />
              </div>
              <span className="agent-card-date">{row.date}</span>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

export function AgentGroup({ onboarding, onAction }: { onboarding: OnboardingState; onAction: Action }) {
  if (onboarding.agentCard === 'none') return null;
  return (
    <section className="agent-group" aria-label="AI">
      <span className="section-label">AI</span>
      {onboarding.agentCard === 'account' ? (
        <Account onboarding={onboarding} onAction={onAction} />
      ) : (
        <div className="agent-card">
          <strong className="agent-card-heading">Set up AI</strong>
          {onboarding.signIn === 'idle' && !onboarding.accountEmail && (
            <p className="agent-card-why">Get {creditNumber(SIGNUP_CREDITS)} free credits and ask AI to improve your prints.</p>
          )}
          <SignInDoor onboarding={onboarding} onAction={onAction} />
          <OwnAccountDoor onAction={onAction} disabled={onboarding.signIn === 'checking'} />
        </div>
      )}
    </section>
  );
}

