        ref={field}
        value={code}
        refused={email.refusal === 'wrong_code' || spent}
        disabled={email.busy}
        onChange={setCode}
        onComplete={(digits) => actions.code(digits)}
      />
      {refusal ? (
        <p className="sign-in-error" role="alert">{refusal}</p>
      ) : (
