const names=['credits-01a-agent-setup','credits-01b-welcome','credits-01c-welcome-back','money-06-account','onboarding-v1-03-sign-in-expired'];
const out=[];
for (const n of names){
  const html=await fetch(n+'.html').then(r=>r.text());
  const f=document.createElement('iframe'); f.style.width='2600px'; f.style.height='1100px'; f.srcdoc=html.replace('href="ds/','href="/canvas/ds/'); document.body.appendChild(f);
  await new Promise(r=>f.onload=r); await new Promise(r=>setTimeout(r,300));
  const d=f.contentDocument;
  // every element with fixed height whose content overflows
  const bad=[...d.querySelectorAll('[style*="height"]')].filter(e=>e.scrollHeight>e.clientHeight+1 && getComputedStyle(e).overflow!=='visible').map(e=>(e.getAttribute('data-n')||e.tagName)+' '+e.clientHeight+'/'+e.scrollHeight);
  const door=d.querySelector('[data-n^="Sign-in"]'); const r=door&&door.getBoundingClientRect();
  out.push(n+': door '+(r?Math.round(r.top)+'-'+Math.round(r.bottom):'none')+' | overflow: '+bad.join('; '));
  f.remove();
}
out.join('\n')

