for (const n of ['credits-01a-agent-setup','credits-01c-welcome-back','onboarding-v1-03-sign-in-expired']){
  const html=await fetch(n+'.html?'+Date.now()).then(r=>r.text());
  const f=document.createElement('iframe'); f.style.width='2600px'; f.style.height='1200px'; f.srcdoc=html.replace('href="ds/','href="/canvas/ds/'); document.body.appendChild(f);
  await new Promise(r=>f.onload=r); await new Promise(r=>setTimeout(r,300));
  const d=f.contentDocument;
  const bad=[...d.querySelectorAll('[style*="height"]')].filter(e=>e.scrollHeight>e.clientHeight+1 && getComputedStyle(e).overflow!=='visible').map(e=>(e.getAttribute('data-n')||e.tagName)+' '+e.clientHeight+'/'+e.scrollHeight);
  out.push(n+': '+(bad.join('; ')||'no clipping'));
  f.remove();
}
out.join('\n')

