from PIL import Image, ImageDraw, ImageFont
import json,os
c=json.load(open('project/canvas.json'))['boards']
names=[l.strip().replace('.dc.html','') for l in open('changed.txt') if l.strip()]
pages={}
for n in names:
    p=c.get(n+'.dc.html',{}).get('page','compositions'); pages.setdefault(p,[]).append(n)
font=ImageFont.truetype('/System/Library/Fonts/Helvetica.ttc',28)
os.makedirs('sheets',exist_ok=True); out=[]
W=1100
for p,l in pages.items():
    l=sorted(l)
    for k in range(0,len(l),8):
        ims=[]
        for n in l[k:k+8]:
            im=Image.open(f'out/{n}.png').convert('RGB'); r=W/im.width; im=im.resize((W,int(im.height*r)))
            if im.height>1600: im=im.crop((0,0,W,1600))
            ims.append((n,im))
        cols=2; rows=[ims[i:i+cols] for i in range(0,len(ims),cols)]
        H=sum(max(im.height for _,im in r)+50 for r in rows)+20
        sheet=Image.new('RGB',(cols*W+60,H),'white'); d=ImageDraw.Draw(sheet); y=10
        for r in rows:
            for j,(n,im) in enumerate(r):
                x=20+j*(W+20); d.text((x,y),n,fill='black',font=font); sheet.paste(im,(x,y+40))
                d.rectangle((x-1,y+39,x+W,y+40+im.height),outline='#bbb')
            y+=max(im.height for _,im in r)+50
        fn=f'sheets/{p}-{k//8+1}.jpg'; sheet.save(fn,quality=82); out.append(fn)
for f in out: print(f, os.path.getsize(f)//1024,'KB')
EOF

