            show(self, View{added, true});
        };
        rows.push_back(std::move(add));
    }
    menu->replace_items(std::move(rows));
}
  if (others.some((other) => other.toLowerCase() === folded)) return `Another printer is already named “${trimmed}”.`;
  return undefined;
}

